/// <summary>
/// CB521_ExciseRegister 
/// Service class for excise lodgement number update with multithread
/// </summary>
class METExciseLodgementUpdateService extends SysOperationServiceBase
{
    public METLodgement lodgement;

}

Method.Source:
    /// <summary>
    /// Process method to initiate the multi thread for business logic
    /// </summary>
    /// <param name = "_contract">Contract class reference</param>
    public void process(METExciseLodgementUpdateContract     _contract)
    {
        BatchHeader                     batchHeader;
        SysOperationServiceController   runTaskController;
        METExciseInformationTable       metExciseInformationTable;
        METExciseRegisterOriginTypes    metExciseRegisterOriginTypes;
        METExciseLodgementUpdateContract     contract;

        while select InventTransType, ItemId, SiteId from metExciseInformationTable
            group by ItemId, SiteId, InventTransType
                where metExciseInformationTable.Lodgement == ''
            exists join metExciseRegisterOriginTypes
                where metExciseRegisterOriginTypes.ReferenceId == metExciseInformationTable.InventTransType &&
                        metExciseRegisterOriginTypes.UpdateLodgement == NoYes::Yes
        {
            if (this.isExecutingInBatch())
            {
                runTaskController = new SysOperationServiceController(classStr(METExciseLodgementUpdateService), methodStr(METExciseLodgementUpdateService, runExciseLodgementUpdate));
            
                contract = runTaskController.getDataContractObject('_contract');

                if (!batchHeader)
                {
                    batchHeader = this.getCurrentBatchHeader();
                }

                contract.parmReferenceId(metExciseInformationTable.InventTransType);
                contract.parmItemId(metExciseInformationTable.ItemId);
                contract.parmSiteId(metExciseInformationTable.SiteId);

                batchHeader.addRuntimeTask(runTaskController, this.getCurrentBatchTask().RecId);
            }
            else
            {
                contract = new METExciseLodgementUpdateContract();

                contract.parmReferenceId(metExciseInformationTable.InventTransType);
                contract.parmItemId(metExciseInformationTable.ItemId);
                contract.parmSiteId(metExciseInformationTable.SiteId);

                this.runExciseLodgementUpdate(contract);
            }
        }

        if (batchHeader)
        {
            batchHeader.save();
        }
    }

/// <summary>
/// Updates the lodgement number on the Excise Information table for the specified contract.
/// Handles both direct and batch execution, and manages available quantity and lodgement assignment logic.
/// </summary>
/// <param name = "_contract">Contract class</param>
public void runExciseLodgementUpdate(METExciseLodgementUpdateContract _contract)
{
    this.runExciseLodgementUpdateActual(_contract);
}

    /// <summary>
    /// Method to use to update the lodgement number on Excise information table
    /// </summary>
    /// <param name = "_contract">METExciseLodgementUpdateContract contract class </param>
    /// <param name = "_refId">InventTransRefId type</param>
    public void runExciseLodgementUpdateActual(METExciseLodgementUpdateContract _contract, InventTransRefId _refId = '')
    {
        METExciseInformationTable       metExciseInformationTablePO;
        METExciseInformationTable       metExciseInformationTable;
        METAvailableQty                 purchAvailableQty;
        METAvailableQty                 purchAvailableQtyOrig;
        METLodgement                    metLodgement;

        try
        {
            if (_refId)
            {
                while select forupdate metExciseInformationTable
                    where metExciseInformationTable.InventTransType == _contract.parmReferenceId()  &&
                        metExciseInformationTable.ItemId == _contract.parmItemId() &&
                        metExciseInformationTable.SiteId == _contract.parmSiteId() &&
                        metExciseInformationTable.Lodgement == '' &&
                        metExciseInformationTable.ReferenceNumber == _refId
                {
                    ttsbegin;
                    if (metExciseInformationTable.InventTransType == InventTransType::InventCounting)
                    {
                        if (InventJournalTrans::findInventTransId(metExciseInformationTable.InventTransId).CountingReasonCode == VendParameters::find().METExciseRegisterExemptReasonCode)
                        {
                            //Skipping transaction if reason code for counting journal matches with the parameter
                            continue;
                        }
                    }

                    this.runExciseLodgementUpdateActualV1(metExciseInformationTable);
                    ttscommit;
                }
            }
            else
            {
                while select forupdate metExciseInformationTable
                    where metExciseInformationTable.InventTransType == _contract.parmReferenceId()  &&
                        metExciseInformationTable.ItemId == _contract.parmItemId() &&
                        metExciseInformationTable.SiteId == _contract.parmSiteId() &&
                        metExciseInformationTable.Lodgement == ''
                {
                    ttsbegin;
                    if (metExciseInformationTable.InventTransType == InventTransType::InventCounting)
                    {
                        if (InventJournalTrans::findInventTransId(metExciseInformationTable.InventTransId).CountingReasonCode == VendParameters::find().METExciseRegisterExemptReasonCode)
                        {
                            //Skipping transaction if reason code for counting journal matches with the parameter
                            continue;
                        }
                    }

                    this.runExciseLodgementUpdateActualV1(metExciseInformationTable);
                    ttscommit;
                }
            }
        }
        catch
        {
            exceptionTextFallThrough();
        }
        
    }

    /// <summary>
    /// Method to use to update the lodgement number on Excise information table
    /// </summary>
    /// <param name = "_contract">METExciseLodgementUpdateContract contract class </param>
    public void runExciseLodgementUpdateActualV1(METExciseInformationTable _metExciseInformationTable)
    { 
        METExciseInformationTable       metExciseInformationTablePO;
        METExciseInformationTable       metExciseInformationTable = _metExciseInformationTable;
        METAvailableQty                 purchAvailableQty;
        METAvailableQty                 purchAvailableQtyOrig;
        METLodgementEXT                 metLodgement;

        container lodgementQtyCon;

        if (_metExciseInformationTable.InventoryQty < 0) // Only for issue transactions
        {
            select sum(AvailableQty) from metExciseInformationTablePO
                order by CreatedDateTime
                    where (metExciseInformationTablePO.InventTransType == InventTransType::Purch ||
                        metExciseInformationTablePO.InventTransType == InventTransType::TransferOrderReceive) &&
                        metExciseInformationTablePO.ItemId == metExciseInformationTable.ItemId &&
                        metExciseInformationTablePO.SiteId == metExciseInformationTable.SiteId &&
                        metExciseInformationTablePO.AvailableQty > 0 &&
                        metExciseInformationTablePO.LodgementClosed == NoYes::No;

            if (metExciseInformationTablePO.AvailableQty < abs(_metExciseInformationTable.InventoryQty))
            {
                Error(strFmt("@MET:LodgementInsufficient", metExciseInformationTable.ReferenceNumber, metExciseInformationTable.ItemId, metExciseInformationTable.SiteId));
                return;
            }
        }

        metExciseInformationTablePO = null;

        select forupdate metExciseInformationTablePO
            order by CreatedDateTime
                where (metExciseInformationTablePO.InventTransType == InventTransType::Purch ||
                    metExciseInformationTablePO.InventTransType == InventTransType::TransferOrderReceive) &&
                    metExciseInformationTablePO.ItemId == metExciseInformationTable.ItemId &&
                    metExciseInformationTablePO.SiteId == metExciseInformationTable.SiteId &&
                    metExciseInformationTablePO.AvailableQty > 0 &&
                    metExciseInformationTablePO.LodgementClosed == NoYes::No;

        if (metExciseInformationTablePO.RecId != 0)
        {
            purchAvailableQty  =  metExciseInformationTablePO.AvailableQty + metExciseInformationTable.InventoryQty;
            metLodgement = metExciseInformationTablePO.Lodgement;

            if (purchAvailableQty > 0)
            {
                lodgementQtyCon += [metExciseInformationTablePO.Lodgement, abs(metExciseInformationTable.InventoryQty)];

                metExciseInformationTablePO.AvailableQty = purchAvailableQty;
                metExciseInformationTablePO.update();

                metExciseInformationTable.Lodgement = metExciseInformationTablePO.Lodgement;
                metExciseInformationTable.LodgementAndQtyCon = lodgementQtyCon;
                metExciseInformationTable.update();
            }
            else
            {
                lodgementQtyCon += [metExciseInformationTablePO.Lodgement, abs(metExciseInformationTablePO.AvailableQty)];

                metExciseInformationTablePO.AvailableQty = 0;
                metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
                metExciseInformationTablePO.update();

                do
                {
                    next metExciseInformationTablePO;

                    if (metExciseInformationTablePO.RecId == 0)
                    {
                        Error(strFmt("@MET:LodgementValidation", metExciseInformationTable.ItemId, metExciseInformationTable.SiteId));
                        break;
                    }
                    purchAvailableQtyOrig = abs(purchAvailableQty);
                    purchAvailableQty  =  metExciseInformationTablePO.AvailableQty + purchAvailableQty;

                    metLodgement = metLodgement + ','+  metExciseInformationTablePO.Lodgement;
                           
                    if (purchAvailableQty > 0)
                    {
                        lodgementQtyCon += [metExciseInformationTablePO.Lodgement, purchAvailableQtyOrig];

                        metExciseInformationTablePO.AvailableQty = purchAvailableQty;
                        metExciseInformationTablePO.update();

                        break;
                    }
                    else
                    {
                        lodgementQtyCon += [metExciseInformationTablePO.Lodgement, metExciseInformationTablePO.AvailableQty];

                        metExciseInformationTablePO.AvailableQty = 0;
                        metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
                        metExciseInformationTablePO.update();
                    }
                }
                while (purchAvailableQty < 0);

                metExciseInformationTable.reread();
                metExciseInformationTable.Lodgement = metLodgement;
                metExciseInformationTable.LodgementAndQtyCon = lodgementQtyCon;
                metExciseInformationTable.update();
            }

            lodgement = metLodgement;

            info(strFmt("@MET:LodgmentUpdate", metExciseInformationTable.ItemId, metExciseInformationTable.SiteId));
        }
        else if (metExciseInformationTable.InventoryQty > 0 && (metExciseInformationTable.InventTransType == InventTransType::Sales ||
                metExciseInformationTable.InventTransType == InventTransType::InventCounting))
        {
            select firstonly forupdate metExciseInformationTablePO
                order by metExciseInformationTablePO.ModifiedDateTime desc
                where metExciseInformationTablePO.InventTransType == InventTransType::Purch
                && metExciseInformationTablePO.ItemId == metExciseInformationTable.ItemId
                && metExciseInformationTablePO.SiteId == metExciseInformationTable.SiteId;

            if (metExciseInformationTablePO.RecId != 0)
            {
                metExciseInformationTablePO.AvailableQty += metExciseInformationTable.InventoryQty;
                metExciseInformationTablePO.LodgementClosed = NoYes::No;
                ttsbegin;
                metExciseInformationTablePO.update();
                ttscommit;
            }
        }
    }

/// <summary>
/// Lodgement calculated value.
/// </summary>
/// <returns>METLodgement</returns>
public METLodgement getMetLodgement()
{
    return lodgement;
}
